  state.frames.front().duration=83;state.frames.push_back({"portable-frame",167,true});state.groups.push_back({"portable-group",U"Source group"});state.layers.front().groupId="portable-group";
  auto& root=state.cels.front();root.opacity=.5;root.zIndex=3;root.surface->width=3;root.surface->height=2;root.surface->offsetX=-1;root.surface->offsetY=1;root.surface->storageOriginX=4;root.surface->storageOriginY=-2;root.surface->pixels=std::vector<Pixel>{0xff123456,0xffabcdef,0,0xff778899,0,0xffaabbcc};
  auto alias=root;alias.id="portable-alias";alias.frameId="portable-frame";alias.linkedCelId=root.id;alias.surface.reset();state.cels.push_back(alias);
  for(bool group:{false,true}){timeline::MaskSlot mask;mask.group=group;mask.ownerId=group?"portable-group":state.layers.front().id;mask.frameId=first;mask.mask.id=group?"portable-group-mask":"portable-layer-mask";mask.mask.surface=timeline::Surface{2,1,-1,1,{},{},{0xff888888,0xffffffff}};auto linked=mask;linked.frameId="portable-frame";linked.mask.id+="-alias";linked.mask.linkedMaskId=mask.mask.id;state.masks.push_back(mask);state.masks.push_back(linked);}
  auto source=Document::fromImported(5,4,std::move(state),seed.palette(),"portable-source",U"Source",std::make_shared<const std::vector<std::uint8_t>>());source.selectFrameHeader(first);source.selectFrameHeader("portable-frame",1);check(source.copySelectedFrames(),"Portable RGBA copy");const auto clip=source.exportFrameClipboard();
  Document target(larger?8:2,larger?7:3);target.addLayer();const auto layer=target.timeline().state().layers.front().id;target.selectLayer(layer);auto destination=target.timeline().state();destination.groups.push_back({"destination-group",U"Target group"});destination.layers.front().groupId="destination-group";destination.layers.front().autoLinkAnimationCels=true;
  target=Document::fromImported(target.width(),target.height(),std::move(destination),target.palette(),"portable-target",U"Target",std::make_shared<const std::vector<std::uint8_t>>());target.clearSourceArchiveForNewSnapshot();const auto history=target.historyPosition(),revision=target.revision();
  auto broken=clip;broken.items.front().cels.front().surface->width=99;rejects([&]{target.pasteFrameClipboard(broken);},"Malformed portable geometry rejects");check(target.revision()==revision&&target.historyPosition()==history&&target.timeline().state().frames.size()==1,"Malformed paste is atomic");
  check(target.pasteFrameClipboard(clip)&&target.historyPosition()==history+1,"Different canvas frame paste is one edit");const auto frames=target.timeline().state().frames;check(frames.size()==3&&frames[1].duration==83&&frames[2].duration==167&&frames[2].disabled,"Portable frame timing and disabled state");
  const auto* pasted=target.timeline().findCel(layer,frames[1].id);const auto* linked=target.timeline().findCel(layer,frames[2].id);const auto rootId=pasted->id,aliasId=linked->id;
  const auto verify=[&](const Document& d){const auto resolved=d.timeline().resolveSurface(aliasId);check(resolved.source&&resolved.source->id==rootId&&resolved.surface,"Portable Cel canonical link");const auto& surface=*resolved.surface;check(surface.width==3&&surface.height==2&&surface.offsetX==-1&&surface.offsetY==1&&surface.pixels==clip.items.front().cels.front().surface->pixels,"Portable sparse geometry and out-of-canvas pixels");check(resolved.source->opacity==.5&&resolved.source->zIndex==3,"Portable Cel properties");check(d.width()==(larger?8:2)&&d.height()==(larger?7:3),"Target canvas unchanged");check(d.timeline().state().masks.size()==4,"Portable layer and group masks");for(bool group:{false,true}){const auto owner=group?std::string("destination-group"):layer;const auto* rootMask=timeline::directMask(d.timeline().state(),owner,frames[1].id);const auto* aliasMask=timeline::directMask(d.timeline().state(),owner,frames[2].id);check(rootMask&&aliasMask&&aliasMask->mask.linkedMaskId==rootMask->mask.id,"Portable mask owner and links");check(timeline::resolvedMask(d.timeline().state(),owner,frames[2].id)->surface.pixels[0]==0xff888888,"Portable resolved mask pixels");}const auto* blank=d.timeline().findCel(d.timeline().state().layers.back().id,frames[2].id);check(blank&&blank->surface&&blank->surface->width==1&&blank->surface->height==1&&blank->surface->pixels.size()==1,"Additional target layer blank slot uses legacy sparse storage");};
  verify(target);verify(*reopen(target));target.undo();check(target.timeline().state().frames.size()==1&&target.timeline().state().masks.empty(),"Portable frame paste undo");target.redo();verify(target);
