// Cross-document frame paste creates missing owners from portable layer
// properties, and adapts editable Cel metadata to the destination layer kind.
void portableFrameLayerMapping(){
 for(bool newText:{false,true}){
  Document seed(2,1);seed.addLayer();auto state=seed.timeline().state();state.groups.push_back({"source-only-group",U"Source group"});
  for(std::size_t i=0;i<state.layers.size();++i){auto& layer=state.layers[i];layer.groupId="source-only-group";layer.kind=i==0||newText?"text":"";layer.name=i?U"Portable owner":U"Source text";layer.displayColor=0xffaabbcc;layer.description=U"Source only";layer.linkedContentId=i&&!newText?"source-only-shared":"";layer.autoLinkAnimationCels=true;timeline::ColorOverlayStyle style;style.overlayEnabled=true;style.color=0xffabcdef;layer.layerStyles=style;
   if(i){layer.visible=false;layer.locked=true;layer.opacity=.4;layer.blendMode="multiply";layer.clippingMask=true;}
   for(auto& cel:state.cels)if(cel.layerId==layer.id){cel.opacity=layer.opacity;cel.surface->pixels=std::vector<Pixel>{0xff123456,0xffabcdef};if(layer.kind=="text"){TextCelData data;data.text=u"Portable";data.originX=1;data.originY=0;cel.text=data;}}
  }
  timeline::MaskSlot mask;mask.group=true;mask.ownerId="source-only-group";mask.frameId=state.frames.front().id;mask.mask.id="source-group-mask";mask.mask.surface=timeline::Surface{1,1,0,0,{},{},{0xffffffff}};state.masks.push_back(mask);
  auto source=Document::fromImported(2,1,std::move(state),seed.palette(),"portable-layer-source",U"Source",std::make_shared<const std::vector<std::uint8_t>>());check(source.copySelectedFrames(),"Portable layer copy");const auto clip=source.exportFrameClipboard();
  Document target(2,1);const auto original=target.layer().id;const auto history=target.historyPosition();check(target.pasteFrameClipboard(clip)&&target.historyPosition()==history+1,"Grouped source adds missing layer in one edit");const auto frame=target.frame().id,newLayer=target.timeline().state().layers.back().id;
  const auto verify=[&](const Document& d){const auto& layers=d.timeline().state().layers;check(layers.size()==2&&layers.front().id==original&&layers.front().kind.empty()&&layers.front().visible&&!layers.front().locked&&layers.front().blendMode=="normal","Existing target owner unchanged");const auto& added=layers.back();check(added.id==newLayer&&added.name==U"Portable owner"&&!added.visible&&added.locked&&added.opacity==.4&&added.blendMode=="multiply"&&added.clippingMask,"New owner keeps portable properties");check(!added.groupId&&added.linkedContentId.empty()&&!added.layerStyles&&!added.displayColor&&added.description.empty()&&!added.autoLinkAnimationCels,"New owner excludes source-only relationships and nonportable properties");check(added.kind==(newText?"text":""),"New owner keeps source kind");const auto* ordinary=d.timeline().findCel(original,frame);const auto* created=d.timeline().findCel(newLayer,frame);check(ordinary&&!ordinary->text&&d.timeline().resolveSurface(ordinary->id).surface->pixels==clip.items.front().cels.front().surface->pixels,"Text into ordinary owner retains pixels without editable text");check(created&&bool(created->text)==newText&&(!newText||created->text->text==u"Portable"),"New text owner keeps editable content");check(d.timeline().state().groups.empty()&&d.timeline().state().masks.empty(),"Unmatched source groups and group masks are not imported");};
  verify(target);verify(*reopen(target));target.undo();check(target.timeline().state().layers.size()==1&&target.timeline().state().frames.size()==1,"Portable layer undo removes created owner");target.redo();verify(target);check(source.timeline().state().layers.back().groupId=="source-only-group","Paste leaves source group unchanged");
 }
}
// workspace-gif-import.test.ts imports into existing time slots and appends
